import{_ as r,a0 as i,w as h,s as l,ao as c,I as p,x as e,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux touch 命令 - 為什麼我們需要改變時間戳？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux touch 命令 - 為什麼我們需要改變時間戳？ | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux touch 命令 - 為什麼我們需要改變時間戳？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux touch 命令 - 為什麼我們需要改變時間戳？ | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Linux touch command - Why do we need to change Timestamp","title":"Linux touch 命令 - 為什麼我們需要改變時間戳？","tag":"201403","desc":""},"relativePath":"201403/Linux touch command - Why do we need to change Timestamp.md","filePath":"[post].md"}'),s={name:"201403/Linux touch command - Why do we need to change Timestamp.md"};function d(m,t,u,g,x,_){const o=i("Link");return h(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-touch-命令-為什麼我們需要改變時間戳" tabindex="-1">Linux touch 命令 - 為什麼我們需要改變時間戳？ <a class="header-anchor" href="#linux-touch-命令-為什麼我們需要改變時間戳" aria-label="Permalink to “Linux touch 命令 - 為什麼我們需要改變時間戳？”">​</a></h1><p>我們可能在 Linux 下運用 touch 命令創建一個空文件。當然我們也可以使用其他命令例如 vi, nano 或是任意一個編輯工具來實現。但是你可能需要更多的步驟來完成操作。其實你要知道 touch 命令的主要功能並不是為了創建一個空文件哦。</p><h3 id="什麼是-touch-命令" tabindex="-1">什麼是 touch 命令 <a class="header-anchor" href="#什麼是-touch-命令" aria-label="Permalink to “什麼是 touch 命令”">​</a></h3><p>眾所周知，每個文件都被附有時間戳。這個時間戳記包括訪問時間和修改時間。而 Touch 命令主要就是用來修改文件的訪問時間和修改時間。</p><h3 id="為什麼我們需要使用-touch-命令" tabindex="-1">為什麼我們需要使用 touch 命令 <a class="header-anchor" href="#為什麼我們需要使用-touch-命令" aria-label="Permalink to “為什麼我們需要使用 touch 命令”">​</a></h3><p>既然 touch 命令描述的是改變時間戳，那麼我們可能會想為什麼我們需要去改變時間戳呢?這個問題會引發我們的深思。然而，我想有個理由可以解釋為什麼我們需要使用它。如果你參加了一個全球範圍的開源項目，那麼時間戳可能變得很重要。編譯源代碼文件可能需要同一地區的時間戳。如果未統一，程序可能會編譯失敗。（譯註：有強迫症的同學也很喜歡這個命令——就看不得亂七八糟的時間，;&gt;）</p><h3 id="不帶任何選項下運行-touch" tabindex="-1">不帶任何選項下運行 touch <a class="header-anchor" href="#不帶任何選項下運行-touch" aria-label="Permalink to “不帶任何選項下運行 touch”">​</a></h3><p>最簡單的使用 touch 命令。只需鍵入：</p><pre><code>$ touch file_name
</code></pre><p>請觀察下面的一張截圖。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch.png" alt="Touch command"></p><p><strong>File_1.txt</strong>原來的時間戳是 12:42。在我們使用 touch 命令後，它改變為了 17:08。由此看出，默認情況下，touch 會將文件的時間戳改為當前時間。</p><h3 id="只改變訪問時間" tabindex="-1">只改變訪問時間 <a class="header-anchor" href="#只改變訪問時間" aria-label="Permalink to “只改變訪問時間”">​</a></h3><p>正如我們之前提到的，每個文件都附有訪問時間和修改時間。上面的時間戳是 17:08。我們可以看更多的細節。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_stat.png" alt="Detail timestamp"></p><p>我們發現<strong>訪問</strong>時間和<strong>修改</strong>時間的值是相同的都是 17:08:35 ,還有它們屬於同一時區 GMT +7。</p><p>如果現在我們要只改變訪問時間，我們需要使用<strong>-a</strong>選項。</p><pre><code>$ touch -a file_1.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_a.png" alt="Touch -a option"></p><p>如你所見，<strong>訪問時間變為</strong>了 17:51:37 ,但是<strong>修改時間仍為</strong>17:08:35。[譯註：原文為 Change time(狀態改變時間)應是作者筆誤]</p><h3 id="只改變修改時間" tabindex="-1">只改變修改時間 <a class="header-anchor" href="#只改變修改時間" aria-label="Permalink to “只改變修改時間”">​</a></h3><p>我們可以使用<strong>-m</strong>選項來實現。現在我們用<strong>file_2.txt</strong>作個示例。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_stat_file_2.png" alt="File_2.txt detail timestamp"></p><pre><code>$ touch -m file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_m.png" alt="Touch -m option"></p><p>現在<strong>修改時間從 12:42:20 改為了 17:57:20。請注意</strong>,當文件被訪問或修改時，狀態改變時間域的值總會對其記錄。</p><h3 id="更改為自定義時間戳" tabindex="-1">更改為自定義時間戳 <a class="header-anchor" href="#更改為自定義時間戳" aria-label="Permalink to “更改為自定義時間戳”">​</a></h3><p><strong>-a</strong>和<strong>-m</strong>選項都會將文件的時間戳改為現在當前時間。當然我們也可以更改為自定義時間戳。使用<strong>-t</strong>選項實現。</p><p>從上面示例示例中的 file_2.txt，我們看出它的時間戳是：</p><pre><code>訪問時間:12:42:20
修改時間:17:57:20
執行日期:2014-01-14
</code></pre><p>假如我們想要將<strong>訪問時間和修改時間</strong>改為<strong>2014年1月12日 09:58:27</strong>。我們可以用下列命令來完成：</p><pre><code>$ touch -t 201401120958.27 file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_t.png" alt="Touch using -t option"></p><p><strong>-t</strong> 選項語法組成 :</p><h4 id="cc-yy-mmddhhmm-ss" tabindex="-1">[[CC]YY]MMDDhhmm [.SS] <a class="header-anchor" href="#cc-yy-mmddhhmm-ss" aria-label="Permalink to “[[CC]YY]MMDDhhmm [.SS]”">​</a></h4><pre><code>CC - 年份的前兩位 
YY - 年份的後兩位 
MM - 月份 [01-12]
DD - 日期 [01-31]
hh - 時 [00-23]
mm - 分 [00-59]
SS - 秒 [00-61]
</code></pre><h3 id="改變日期和時間的另一種方式" tabindex="-1">改變日期和時間的另一種方式 <a class="header-anchor" href="#改變日期和時間的另一種方式" aria-label="Permalink to “改變日期和時間的另一種方式”">​</a></h3><p>如果你覺得<strong>[[CC]YY]MMDDhhmm [.SS]</strong>格式不適合你，我們也可以使用 -d 選項。下面是<strong>-d</strong>選項使用的一個示例。</p><h4 id="更改指定日期" tabindex="-1">更改指定日期 <a class="header-anchor" href="#更改指定日期" aria-label="Permalink to “更改指定日期”">​</a></h4><p>舉例來説，我們有個名為 file_3.txt 的文件，它的相關屬性在下面的截圖中展示了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/stat_file_3.png" alt="File_3.txt detail timestamp"></p><p>現在<strong>我們要將日期2014年1月14日改為2013年12月20日</strong>。可以使用下列命令：</p><pre><code>$ touch -d &#39;10-December-2013&#39; file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_d_date.png" alt="Change date using -d option"></p><p>不出意料，訪問時間和修改時間的日期已經改為了2013年12月10日。</p><h3 id="改變時區" tabindex="-1">改變時區 <a class="header-anchor" href="#改變時區" aria-label="Permalink to “改變時區”">​</a></h3><p>如果我們想改變指定GMT的時間，我們也可以使用<strong>-d</strong>選項。先讓file_3.txt 移回當前時間。</p><pre><code>$ touch file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_return_file_3.png" alt="Reset file_3.txt timestamp"></p><p>不難發現 file_3.txt 的時區為 GMT +0700。要改為 GMT3 時區，我們只需要鍵入如下命令：</p><pre><code>$ touch -d GMT3 file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_gmt3.png" alt="Change into GMT3 timezone"></p><p>好的，現在時間已經改為了 10:00:00 AM。</p><h3 id="結合參數下使用-d選項" tabindex="-1">結合參數下使用-d選項 <a class="header-anchor" href="#結合參數下使用-d選項" aria-label="Permalink to “結合參數下使用-d選項”">​</a></h3><p>還可以用很酷的方式使用<strong>-d</strong>選項。請觀察下面的圖片。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_next_sunday.png" alt="Change date using keyword"></p><p>我們可以將單詞 <strong>next Sunday</strong> 和 GMT 3合成一個值，而 touch 命令仍然能識別它。日期已經改為了2014年1月21日，而當前的日期為2014年1月14日。</p><p>還有另一個<strong>-d</strong>選項的示例。 首先，我們要將file3_3.txt重置到當前日期和時間。</p><pre><code>$ touch file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_reset_file_3.png" alt="Reset file_3.txt timestamp"></p><p>然後我們嘗試這個命令：</p><pre><code>$ touch -d ‘1 year ago 13:43:07’ file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_d_year_ago.png" alt="Change date using keyword"></p><p>太震撼了，Touch 甚至能識別單詞‘<strong>1 year ago</strong>’。現在的日期以及時間已經改為了2013年1月14日,13:43:07。</p><h3 id="創建一個空文件" tabindex="-1">創建一個空文件 <a class="header-anchor" href="#創建一個空文件" aria-label="Permalink to “創建一個空文件”">​</a></h3><p>當你運行 touch 命令目標文件不存在時，touch 會創建一個同名的空文件。</p><pre><code>$ touch file_10.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_file_10.png" alt="Create an empty file"></p><h3 id="同時創建多個文件" tabindex="-1">同時創建多個文件 <a class="header-anchor" href="#同時創建多個文件" aria-label="Permalink to “同時創建多個文件”">​</a></h3><p>你可以用空格將目標文件分割開來，以此來創建多個文件。</p><pre><code>$ touch doc_10.txt doc_20.txt doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_multiple_files.png" alt="Create multiple files"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你要處理關於文件或目錄的時間戳問題，那麼 Touch 會對你很有用的。一如既往得你也可以鍵入<strong>man touch</strong>或<strong>touch --help</strong>來顯示幫助頁面瞭解更多細節。</p><hr>`,75)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://linoxide.com/linux-command/linux-touch-command/"},{default:a(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-touch-command/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(o,{href:"https://github.com/Luoxcat"},{default:a(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const C=r(s,[["render",d]]);export{b as __pageData,C as default};
